/* MODULE tn05 · Bước 6 Thử nghiệm · Ra mắt sản phẩm là bài toán thứ tự
   9 bài × 7 câu. Đi vào từng bước của một lần ra mắt. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'tn05', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:tn05-01', skill:'measure', read:'6 phút', t:'Ra mắt toàn quốc ngay hay bán thử ở một vùng trước?',
  situation:'Một hãng nước uống ở Bình Dương làm xong dòng trà thảo mộc đóng chai. Giám đốc muốn phủ 3.000 cửa hàng trên cả nước trong tháng đầu, kèm quảng cáo trên TikTok và YouTube. Bạn đề xuất bán thử ở 150 cửa hàng tại Thủ Dầu Một trong 6 tuần trước. Giám đốc hỏi: thử như vậy mất thời gian, đối thủ bắt chước thì sao?',
  concept:{ name:'Ra mắt mềm (soft launch)',
    body:'Ra mắt mềm là bán thật, cho khách thật trả tiền thật, nhưng ở phạm vi nhỏ. Mục tiêu không phải doanh số mà là <b>trả lời vài câu hỏi trước khi chi lớn</b>: khách có mua lại không, hàng có về kịp cửa hàng không, giá có ổn không, bao bì có bị bỏ qua trên kệ không. Chỉ số quan trọng nhất ở giai đoạn này thường là <b>tỉ lệ mua lại</b>, vì lần mua đầu có thể do tò mò hay khuyến mãi, còn lần thứ hai mới cho biết sản phẩm có chỗ trong đời sống của khách. Soft launch đáng giá khi cái giá của một lần ra mắt hỏng lớn hơn nhiều so với vài tuần chậm.' },
  example:'Sau 6 tuần ở 150 cửa hàng: 2.400 khách mua lần đầu, 480 người mua lần hai, tỉ lệ mua lại 20%. Hãng đặt ngưỡng trước là 30%. Phỏng vấn nhanh ở quầy cho thấy nhiều người chê vị đắng hậu. Hãng giảm độ đắng, thử thêm 4 tuần, mua lại lên 34%. Nếu phủ thẳng 3.000 cửa hàng với công thức cũ, phần lớn ngân sách quảng cáo sẽ đổ vào một sản phẩm khách thử một lần rồi thôi.',
  takeaway:'Bán thử nhỏ để biết khách có quay lại không; chi lớn chỉ sau khi con số mua lại vượt ngưỡng đã đặt.',
  apply:'Chọn một sản phẩm sắp ra mắt ở nơi bạn làm. Nói trong 60 giây: vùng thử nào, bao lâu, và con số nào phải đạt thì mới mở rộng.',
  mistakes:['Đo soft launch bằng doanh số tổng thay vì tỉ lệ mua lại.','Không đặt ngưỡng trước, xong rồi mới giải thích kết quả theo ý mình.','Thử ở vùng quá đặc biệt (gần nhà máy, nhiều người quen) nên số đẹp giả.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong 6 tuần bán thử một loại nước uống mới, con số nào nói nhiều nhất về việc có nên mở rộng?',
    options:[{k:'a',t:'Tổng số chai bán được trong 6 tuần'},{k:'b',t:'Tỉ lệ khách đã mua lần đầu quay lại mua lần hai'},
             {k:'c',t:'Số lượt xem video giới thiệu sản phẩm trên TikTok trong vùng thử'},{k:'d',t:'Số cửa hàng đồng ý nhận hàng trong tuần đầu tiên'}],
    answer:'b', why:{a:'Doanh số tổng gộp cả người mua vì tò mò; nó không cho biết khách có giữ sản phẩm lại không.',
      b:'Đúng. Lần mua thứ hai là bằng chứng sản phẩm được chọn lại, không chỉ được thử.',
      c:'Lượt xem đo sự chú ý, không đo việc khách uống xong có muốn uống nữa không.',
      d:'Cửa hàng nhận hàng là điều kiện cần, nhưng nói về nhà phân phối, không nói về người uống.'} },
  { type:'mcq', stem:'Giám đốc sợ đối thủ bắt chước trong 6 tuần bán thử. Bạn chọn cách nào để giữ được lợi ích của soft launch?',
    options:[{k:'a',t:'Giữ bán thử nhưng rút ngắn, đặt ngưỡng mua lại trước và chuẩn bị sẵn hàng để mở rộng'},{k:'b',t:'Bỏ bán thử, ra mắt toàn quốc ngay để chiếm chỗ trước khi đối thủ kịp phản ứng'},
             {k:'c',t:'Bán thử ở vùng xa như Cà Mau để đối thủ ở TP.HCM không nhìn thấy'},{k:'d',t:'Bán thử nhưng giấu tên thương hiệu, dùng một nhãn tạm để đối thủ không nhận ra'}],
    answer:'a', why:{a:'Đúng. Rủi ro bị bắt chước giảm bằng tốc độ ra quyết định, không phải bằng việc bỏ bước kiểm tra.',
      b:'Chiếm chỗ bằng một công thức khách không mua lại thì đối thủ chỉ cần chờ bạn tự rút khỏi kệ.',
      c:'Vùng thử phải giống thị trường chính; một vùng quá khác cho con số không dùng được.',
      d:'Nhãn tạm làm kết quả thử sai lệch, vì khách phản ứng với cả thương hiệu chứ không chỉ với vị.'} },
  { type:'calc', stem:'Bán thử: 2.400 khách mua lần đầu, 480 người mua lần hai. Tỉ lệ mua lại là bao nhiêu phần trăm?',
    unit:'%', ans:20, tol:0.1, wrong:[[500,'SAI_MAU_SO'],[16.7,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ mua lại = số người mua lần hai ÷ số người mua lần đầu.','480 ÷ 2.400 = 0,2 = <b>20%</b>.'] },
  { type:'mcq', stem:'Vùng bán thử có tỉ lệ mua lại 45%, nhưng 150 cửa hàng thử đều nằm quanh nhà máy, nhiều công nhân của hãng mua. Bạn đọc con số này thế nào?',
    options:[{k:'a',t:'Rất tốt, vượt xa ngưỡng 30% nên mở rộng toàn quốc ngay'},{k:'b',t:'Chưa đủ vì 6 tuần quá ngắn, cần ít nhất một năm mới biết'},
             {k:'c',t:'Công nhân cũng là khách hàng thật nên con số vẫn đại diện tốt'},{k:'d',t:'Có thể bị thổi phồng, cần thử thêm ở vùng giống thị trường chính'}],
    answer:'d', why:{a:'Con số đẹp đến từ một nhóm khách thân với hãng; mở rộng dựa vào nó dễ vỡ.',
      b:'Vài tuần thường đủ để thấy mua lại với hàng tiêu dùng nhanh; vấn đề ở đây là mẫu, không phải thời gian.',
      c:'Họ trả tiền thật, nhưng có lý do mua (quen, ủng hộ công ty) mà khách ngoài không có.',
      d:'Đúng. Vùng thử phải giống nơi bạn sẽ bán; mẫu lệch cho con số lệch.'} },
  { type:'mcq', stem:'Một app giao đồ ăn mới muốn ra mắt ở Đà Nẵng trước Hà Nội và TP.HCM. Lý do hợp lý nhất cho lựa chọn này là gì?',
    options:[{k:'a',t:'Đà Nẵng là thị trường lớn nhất nên cần chiếm trước'},{k:'b',t:'Thành phố vừa đủ lớn để có số liệu, lỗi xảy ra thì thiệt hại nhỏ'},
             {k:'c',t:'Ở Đà Nẵng chi phí quảng cáo rẻ nên con số nào cũng sẽ đẹp hơn thật'},{k:'d',t:'Đối thủ lớn không hoạt động ở Đà Nẵng nên sẽ không có cạnh tranh gì'}],
    answer:'b', why:{a:'Đà Nẵng không phải thị trường lớn nhất; lý do chọn là quy mô vừa để học.',
      b:'Đúng. Soft launch chọn nơi đủ người để đo, đủ nhỏ để sửa sai rẻ.',
      c:'Chọn nơi làm con số đẹp giả là tự lừa mình; vùng thử phải giúp dự đoán vùng thật.',
      d:'Các app lớn đều có mặt ở Đà Nẵng; và nếu không có cạnh tranh thì kết quả lại càng khó suy ra cho nơi khác.'} },
  { type:'mcq', stem:'Trước khi soft launch, việc nào cần làm để kết quả thử không bị giải thích theo ý thích?',
    options:[{k:'a',t:'Ghi ra ngưỡng mở rộng, ngưỡng sửa và ngưỡng dừng trước khi bán'},{k:'b',t:'Mời thật nhiều khách quen dùng thử để có phản hồi tích cực ban đầu'},
             {k:'c',t:'Chạy khuyến mãi mua một tặng một để có thật nhiều người mua lần đầu'},{k:'d',t:'Đợi có kết quả rồi mới họp để thống nhất con số nào là tốt cho sản phẩm'}],
    answer:'a', why:{a:'Đúng. Ngưỡng đặt trước biến thử nghiệm thành quyết định, không thành cuộc tranh luận.',
      b:'Khách quen cho phản hồi dễ chịu, không đại diện cho khách lạ.',
      c:'Khuyến mãi mạnh kéo người mua lần đầu vì giá, làm tỉ lệ mua lại khó đọc.',
      d:'Đặt ngưỡng sau khi thấy số thì ai cũng chọn ngưỡng vừa khớp mong muốn của mình.'} },
  { type:'mcq', stem:'Trường hợp nào soft launch ÍT đáng làm nhất?',
    options:[{k:'a',t:'Sản phẩm cần đầu tư dây chuyền lớn, khó quay đầu'},{k:'b',t:'Một phiên bản hương vị theo mùa bán 4 tuần, chi phí nhỏ'},
             {k:'c',t:'Một loại sữa mới cho trẻ em, cần niềm tin rất cao từ phụ huynh'},{k:'d',t:'Ra mắt ở kênh siêu thị, nơi rút hàng khỏi kệ tốn phí và mất uy tín'}],
    answer:'b', why:{a:'Chi phí sai lầm cao là lúc soft launch đáng giá nhất.',
      b:'Đúng. Hàng bán ngắn hạn, rủi ro nhỏ: thử trước tốn gần bằng làm luôn.',
      c:'Niềm tin khó xây lại; hỏng một lần thì thiệt lâu, nên thử nhỏ trước rất đáng.',
      d:'Rút khỏi kệ siêu thị tốn kém và để lại tiếng xấu với người mua hàng; thử trước giúp tránh việc đó.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:tn05-02', skill:'channel', read:'7 phút', t:'Quảng cáo đã chạy mà khách ra tiệm không thấy hàng',
  situation:'Một hãng bánh snack ra mắt vị mới, chạy quảng cáo trên YouTube và TikTok toàn quốc ngay từ ngày 1 với ngân sách 600 triệu đồng cho tháng đầu. Đến tuần thứ hai, đội bán hàng báo: hàng mới chỉ có mặt ở 30% cửa hàng tạp hoá mục tiêu. Bình luận dưới video có nhiều câu kiểu: "Tìm mãi không thấy bán ở đâu".',
  concept:{ name:'Phủ hàng trước, quảng cáo sau',
    body:'Quảng cáo tạo ý muốn mua, nhưng ý muốn chỉ thành doanh số khi khách gặp được hàng. Chỉ số cần theo dõi là <b>độ phủ</b>: tỉ lệ điểm bán mục tiêu đang có hàng trên kệ. Nếu độ phủ thấp, phần lớn tiền quảng cáo rơi vào những người không thể mua, và họ còn có trải nghiệm tệ: tìm không thấy, lấy hàng đối thủ. Thứ tự đúng là đưa hàng tới điểm bán, kiểm tra hàng đã lên kệ thật, rồi mới bật quảng cáo diện rộng. Nếu buộc phải chạy sớm, hãy giới hạn quảng cáo theo vùng đã có hàng.' },
  example:'Độ phủ 30% nghĩa là khoảng 70% người xem quảng cáo sống quanh những tiệm chưa có hàng. Với 600 triệu đồng, khoảng 420 triệu đồng đang tạo nhu cầu không có chỗ mua. Hãng tạm cắt quảng cáo toàn quốc, chỉ chạy ở các quận đã phủ trên 70%, dồn đội bán hàng đưa hàng ra tiệm trong 3 tuần, rồi mới bật lại diện rộng khi độ phủ chung đạt 65%.',
  takeaway:'Tiền quảng cáo chỉ sinh doanh số ở nơi khách với tới được hàng; đo độ phủ trước khi bật quảng cáo.',
  apply:'Nói trong 60 giây: với sản phẩm bạn biết, ai kiểm tra hàng đã lên kệ thật, bằng cách nào, trước ngày quảng cáo chạy.',
  mistakes:['Tin báo cáo "đã giao hàng cho nhà phân phối" là hàng đã lên kệ.','Chạy quảng cáo toàn quốc khi hàng mới có ở vài tỉnh.'],
  q:[
  { type:'mcq', stem:'Đoán trước: quảng cáo cho sản phẩm mới đã chạy rầm rộ nhưng doanh số tuần đầu thấp. Nguyên nhân nào nên kiểm tra đầu tiên?',
    options:[{k:'a',t:'Nội dung quảng cáo chưa đủ hấp dẫn nên cần làm lại video'},{k:'b',t:'Giá bán cao hơn đối thủ nên khách chưa muốn thử'},
             {k:'c',t:'Hàng đã thật sự có mặt trên kệ ở những nơi khách hay mua chưa'},{k:'d',t:'Khách cần thời gian nhìn thấy quảng cáo nhiều lần hơn mới mua'}],
    answer:'c', why:{a:'Có thể, nhưng làm lại video tốn kém; nếu hàng không có ở tiệm thì video nào cũng không cứu được.',
      b:'Giá có thể là vấn đề, nhưng chỉ đọc được khi khách đã đứng trước hàng.',
      c:'Đúng. Kiểm tra độ phủ rẻ và nhanh; không có hàng thì mọi chỉ số khác đều vô nghĩa.',
      d:'Tần suất có ảnh hưởng, nhưng đó là giả thuyết đắt nhất để thử và nên đứng sau việc kiểm tra kệ.'} },
  { type:'mcq', stem:'Tuần thứ hai, độ phủ 30%, còn 450 triệu đồng quảng cáo chưa chi. Bạn làm gì?',
    options:[{k:'a',t:'Chạy tiếp toàn quốc để giữ đà, đội bán hàng sẽ theo kịp sau'},{k:'b',t:'Tăng ngân sách để khách hỏi nhiều, tiệm sẽ tự nhập hàng về bán'},
             {k:'c',t:'Dừng toàn bộ quảng cáo và dời lịch ra mắt sang năm sau cho chắc'},{k:'d',t:'Chỉ chạy ở vùng đã phủ tốt, dồn sức đưa hàng ra tiệm rồi mới mở rộng'}],
    answer:'d', why:{a:'Mỗi ngày chạy toàn quốc là thêm tiền rơi vào nơi không có hàng.',
      b:'Khách hỏi có thể kéo tiệm nhập, nhưng chậm và không chắc; phần lớn khách lấy hàng khác và quên.',
      c:'Dừng hẳn làm mất đà ở những nơi đã có hàng; vấn đề là phạm vi, không phải toàn bộ kế hoạch.',
      d:'Đúng. Khớp vùng quảng cáo với vùng có hàng, và sửa phủ hàng trước khi mở rộng.'} },
  { type:'mcq', stem:'Nhà phân phối báo "đã nhận đủ 100% hàng". Vì sao con số này chưa đủ để bật quảng cáo?',
    options:[{k:'a',t:'Hàng nằm ở kho nhà phân phối chưa chắc đã lên kệ ở tiệm'},{k:'b',t:'Nhà phân phối thường báo sai số lượng để được thưởng thêm'},
             {k:'c',t:'Quảng cáo luôn phải chạy sau ra mắt ít nhất ba tháng'},{k:'d',t:'Nhà phân phối không được phép bán hàng mới trong tháng đầu'}],
    answer:'a', why:{a:'Đúng. Có ba chặng: nhà phân phối, tiệm nhận hàng, hàng lên kệ. Chỉ chặng cuối khách nhìn thấy.',
      b:'Không cần giả định gian lận; kể cả báo đúng thì hàng vẫn có thể đang nằm ở kho.',
      c:'Không có quy tắc cứng như vậy; điều kiện là hàng đã lên kệ, không phải số tháng.',
      d:'Không có ràng buộc đó; nhà phân phối muốn bán càng nhanh càng tốt.'} },
  { type:'calc', stem:'Ngân sách quảng cáo tháng đầu 600 triệu đồng, chạy đều toàn quốc. Độ phủ hàng là 30%. Ước tính bao nhiêu triệu đồng đang chi cho người sống quanh những tiệm chưa có hàng?',
    unit:'triệu đồng', ans:420, tol:1, wrong:[[180,'NHAM_TI_LE_ROI'],[200,'SAI_TINH_TOAN']], errors:['NHAM_TI_LE_ROI'],
    steps:['Phần chưa có hàng = 100% − 30% = 70%.','600 × 70% = <b>420 triệu đồng</b>.'] },
  { type:'mcq', stem:'Một thương hiệu mỹ phẩm bán online mở bán sản phẩm mới trên Shopee. Việc "phủ hàng trước" trong trường hợp này tương ứng với điều gì?',
    options:[{k:'a',t:'Đăng sản phẩm lên càng nhiều sàn càng tốt trước ngày mở bán'},{k:'b',t:'Kho đủ hàng, trang sản phẩm đã duyệt và mã giảm giá đã chạy thử'},
             {k:'c',t:'Chờ đủ 100 đánh giá năm sao rồi mới bắt đầu chạy quảng cáo'},{k:'d',t:'Bán online thì không cần phủ hàng vì khách nào cũng mua được ngay'}],
    answer:'b', why:{a:'Nhiều sàn chưa chắc tốt; một sàn chưa sẵn sàng còn tệ hơn không có mặt.',
      b:'Đúng. Online, "kệ" là trang sản phẩm và kho: hết hàng, trang lỗi, mã hỏng đều giống kệ trống.',
      c:'Đánh giá quan trọng, nhưng sản phẩm mới không thể chờ 100 đánh giá trước khi có người mua.',
      d:'Online vẫn hết hàng, vẫn lỗi trang; khách bấm vào mà không mua được thì tiền quảng cáo mất như thường.'} },
  { type:'mcq', stem:'Hàng đã lên kệ ở 75% tiệm, nhưng khảo sát cho thấy phần lớn nằm ở tầng dưới cùng, bị hàng khác che. Điều này nói gì?',
    options:[{k:'a',t:'Độ phủ đạt rồi, giờ chỉ cần tăng ngân sách quảng cáo lên'},{k:'b',t:'Tiệm không muốn bán nên phải đổi sang nhà phân phối khác'},
             {k:'c',t:'Sản phẩm bị chê nên tiệm cố tình giấu đi, cần đổi công thức'},{k:'d',t:'Có mặt chưa đủ: khách phải nhìn thấy hàng khi đứng trước kệ'}],
    answer:'d', why:{a:'Hàng bị che thì khách vẫn không thấy; quảng cáo thêm chỉ làm khách tìm mà không ra.',
      b:'Vị trí xấu là chuyện thường với hàng mới; giải pháp là thoả thuận trưng bày, không phải đổi nhà phân phối.',
      c:'Không có dấu hiệu tiệm chê sản phẩm; hàng mới chưa có doanh số nên thường bị xếp ở chỗ kém.',
      d:'Đúng. Độ phủ đo sự có mặt; cần thêm độ hiển thị: vị trí, số mặt hàng, vật phẩm tại quầy.'} },
  { type:'mcq', stem:'Chuỗi trà sữa ra món mới, quảng cáo chạy từ thứ Hai nhưng nguyên liệu chỉ về đủ ở 40% cửa hàng từ thứ Năm. Sửa thế nào hợp lý nhất?',
    options:[{k:'a',t:'Giữ lịch quảng cáo, nhân viên xin lỗi và mời khách chọn món khác'},{k:'b',t:'Cho cửa hàng thiếu nguyên liệu ghi "tạm hết" trên menu cả tuần đầu'},
             {k:'c',t:'Lùi quảng cáo tới khi nguyên liệu đã về đủ, hoặc chỉ nhắm quanh cửa hàng có món'},{k:'d',t:'Chuyển toàn bộ tiền quảng cáo sang giảm giá món cũ để bù doanh số'}],
    answer:'c', why:{a:'Khách đến vì món mới mà không có, dù được xin lỗi, vẫn là trải nghiệm hỏng đầu tiên với món đó.',
      b:'"Tạm hết" ngay tuần ra mắt làm món mới mất uy tín trước khi ai kịp thử.',
      c:'Đúng. Khớp lịch quảng cáo với lịch nguyên liệu, hoặc khớp vùng quảng cáo với cửa hàng đã sẵn sàng.',
      d:'Bỏ quảng cáo món mới không giải quyết vấn đề; món mới vẫn cần được giới thiệu khi đã sẵn sàng.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:tn05-03', skill:'comm', read:'6 phút', t:'Nhân viên quầy chưa biết món mới thì ai giới thiệu cho khách?',
  situation:'Một chuỗi 40 cửa hàng cà phê ra dòng đồ uống kem muối. Tài liệu đào tạo gửi qua nhóm Zalo một ngày trước ra mắt. Tuần đầu, 12 cửa hàng có quản lý tự tổ chức buổi uống thử cho nhân viên. Ở 12 cửa hàng đó, 18% hoá đơn có món mới; ở 28 cửa hàng còn lại chỉ 7%. Khách hỏi "món này vị gì" thì nhân viên đáp "em cũng chưa uống".',
  concept:{ name:'Nội bộ là khán giả đầu tiên',
    body:'Trước khi thuyết phục khách, phải thuyết phục những người đứng giữa sản phẩm và khách: nhân viên quầy, đội bán hàng, chủ tiệm tạp hoá, tư vấn viên. Họ trả lời câu hỏi, gợi ý món, xếp hàng lên kệ. Nếu họ không hiểu hay không tin sản phẩm, quảng cáo tốt đến đâu cũng tắt ở quầy. Ra mắt nội bộ cần ba thứ: <b>họ đã tự dùng thử</b>, họ nói được một câu vì sao nên chọn, và họ biết trả lời hai ba câu hỏi hay gặp. Việc này phải xong trước ngày khách đầu tiên bước vào.' },
  example:'Chênh lệch 18% và 7% gợi ý phần lớn khoảng cách đến từ đào tạo, vì 40 cửa hàng cùng giá và cùng quảng cáo. Chuỗi tổ chức uống thử ở 28 cửa hàng còn lại trong tuần thứ hai, kèm một thẻ nhỏ ở quầy với câu gợi ý: "Anh chị thử kem muối không, béo mà không ngấy". Hai tuần sau, tỉ lệ hoá đơn có món mới ở nhóm này lên 15%.',
  takeaway:'Người đứng quầy phải uống thử và nói được một câu về món mới trước khi khách đầu tiên hỏi.',
  apply:'Viết một câu gợi ý dài dưới 15 chữ mà nhân viên có thể nói với khách về một sản phẩm bạn biết.',
  mistakes:['Gửi tài liệu qua nhóm chat rồi coi như đã đào tạo.','Đào tạo quản lý nhưng không tới được nhân viên ca tối, ca cuối tuần.'],
  q:[
  { type:'mcq', stem:'Đoán trước: cùng một món mới, cùng quảng cáo, vì sao cửa hàng này bán gấp đôi cửa hàng kia?',
    options:[{k:'a',t:'Nhân viên ở đó đã thử món và chủ động gợi ý cho khách'},{k:'b',t:'Cửa hàng đó nằm ở khu dân cư có thu nhập cao hơn hẳn'},
             {k:'c',t:'Cửa hàng đó có nhiều khách quen nên ai cũng thử món mới'},{k:'d',t:'Cửa hàng đó treo poster lớn hơn nên khách dễ nhìn thấy hơn'}],
    answer:'a', why:{a:'Đúng. Trong một chuỗi cùng giá, cùng quảng cáo, người đứng quầy thường tạo khác biệt lớn nhất.',
      b:'Thu nhập có ảnh hưởng, nhưng khó giải thích mức chênh gấp đôi khi các cửa hàng khác cũng ở khu tương tự.',
      c:'Khách quen thường gọi món cũ; họ thử món mới khi có người gợi ý.',
      d:'Poster giúp khách biết món có, nhưng quyết định gọi thường xảy ra trong vài giây trao đổi ở quầy.'} },
  { type:'mcq', stem:'Còn 5 ngày đến ra mắt món mới cho 40 cửa hàng. Bạn chọn làm gì với nhân viên?',
    options:[{k:'a',t:'Gửi video hướng dẫn pha chế qua nhóm Zalo cho tất cả nhân viên xem'},{k:'b',t:'Mỗi cửa hàng uống thử cả ca, tập một câu gợi ý và hai câu trả lời hay gặp'},
             {k:'c',t:'Chỉ đào tạo quản lý cửa hàng, quản lý sẽ tự truyền đạt lại cho nhân viên'},{k:'d',t:'Treo thêm poster tại quầy để khách tự đọc, nhân viên không cần giới thiệu'}],
    answer:'b', why:{a:'Video dạy cách pha, không dạy cách giới thiệu; và nhiều người không xem hết.',
      b:'Đúng. Tự uống, có câu nói sẵn, biết trả lời: ba thứ để nhân viên tự tin gợi ý.',
      c:'Truyền đạt qua một tầng thường rơi rớt, nhất là với ca tối và nhân viên bán thời gian.',
      d:'Poster không trả lời được câu "vị gì, có ngọt không" mà khách hay hỏi.'} },
  { type:'calc', stem:'Một cửa hàng có 1.000 hoá đơn/tuần. Trước đào tạo, 7% hoá đơn có món mới; sau đào tạo lên 15%. Mỗi tuần cửa hàng bán thêm bao nhiêu hoá đơn có món mới?',
    unit:'hoá đơn', ans:80, tol:0.5, wrong:[[8,'NHAM_DIEM_PHAN_TRAM'],[150,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Trước: 1.000 × 7% = 70 hoá đơn. Sau: 1.000 × 15% = 150 hoá đơn.','Tăng thêm: 150 − 70 = <b>80 hoá đơn</b>.'] },
  { type:'mcq', stem:'Một hãng sữa chua uống giao hàng mới cho 5.000 tiệm tạp hoá. Ai là "nội bộ" cần hiểu sản phẩm trước tiên?',
    options:[{k:'a',t:'Người tiêu dùng cuối cùng ở các khu dân cư quanh tiệm'},{k:'b',t:'Các KOL sẽ quay video giới thiệu sản phẩm trên TikTok'},
             {k:'c',t:'Nhân viên bán hàng của hãng và các chủ tiệm tạp hoá'},{k:'d',t:'Ban giám đốc để duyệt ngân sách quảng cáo cho đợt ra mắt'}],
    answer:'c', why:{a:'Người tiêu dùng là đích đến, nhưng họ gặp sản phẩm qua tiệm; tiệm phải hiểu trước.',
      b:'KOL giúp tạo chú ý, nhưng không đứng ở 5.000 tiệm để trả lời khách.',
      c:'Đúng. Nhân viên bán hàng thuyết phục tiệm nhập hàng; chủ tiệm quyết định để hàng ở đâu và gợi ý cho khách.',
      d:'Ban giám đốc đã duyệt dự án; họ không đứng giữa sản phẩm và khách.'} },
  { type:'mcq', stem:'Sau buổi đào tạo, quản lý hỏi làm sao biết nhân viên đã sẵn sàng. Cách kiểm tra nào tốt nhất?',
    options:[{k:'a',t:'Cho nhân viên làm bài trắc nghiệm về thành phần và cách pha món'},{k:'b',t:'Đếm số nhân viên đã bấm "đã xem" tài liệu trong nhóm Zalo'},
             {k:'c',t:'Hỏi nhân viên có thích món mới không, ai thích thì coi như sẵn sàng'},{k:'d',t:'Đóng vai khách hỏi món mới và nghe nhân viên trả lời thật trong 30 giây'}],
    answer:'d', why:{a:'Biết thành phần chưa chắc nói được với khách một cách tự nhiên.',
      b:'"Đã xem" không có nghĩa là hiểu hay nhớ.',
      c:'Thích món là tốt, nhưng thích mà không nói được thì khách vẫn không biết vì sao nên chọn.',
      d:'Đúng. Kiểm tra đúng hành vi cần có: nói với khách ở quầy.'} },
  { type:'mcq', stem:'Một ngân hàng ra thẻ tín dụng mới, quảng cáo lớn, nhưng giao dịch viên ở chi nhánh không nắm ưu đãi. Rủi ro lớn nhất là gì?',
    options:[{k:'a',t:'Khách đã quan tâm tới quầy nhưng nhận câu trả lời mơ hồ rồi bỏ đi'},{k:'b',t:'Quảng cáo lớn khiến chi phí ra mắt đội lên vượt kế hoạch'},
             {k:'c',t:'Giao dịch viên sẽ bán nhầm sang sản phẩm vay tiêu dùng'},{k:'d',t:'Đối thủ biết được ưu đãi và tung ra thẻ tương tự ngay'}],
    answer:'a', why:{a:'Đúng. Quảng cáo đưa khách tới, nhưng người đứng quầy quyết định khách có mở thẻ không.',
      b:'Chi phí là chuyện đã biết trước; rủi ro là chi phí đó không ra kết quả.',
      c:'Có thể xảy ra, nhưng hậu quả chính là khách không mở thẻ đang được quảng cáo.',
      d:'Đối thủ biết ưu đãi qua quảng cáo đằng nào cũng biết; không liên quan tới việc đào tạo.'} },
  { type:'mcq', stem:'Ngân sách đào tạo có hạn, chuỗi 40 cửa hàng chỉ tổ chức được uống thử ở 15 cửa hàng trước ra mắt. Chọn cửa hàng nào?',
    options:[{k:'a',t:'15 cửa hàng có doanh số thấp nhất để giúp họ cải thiện'},{k:'b',t:'15 cửa hàng có nhiều hoá đơn nhất, nơi món mới gặp nhiều khách nhất'},
             {k:'c',t:'15 cửa hàng gần văn phòng nhất để tiện cho người đi đào tạo'},{k:'d',t:'Bốc thăm ngẫu nhiên 15 cửa hàng để đảm bảo công bằng cho tất cả'}],
    answer:'b', why:{a:'Cửa hàng yếu cần giúp, nhưng tuần ra mắt thì ưu tiên nơi có nhiều lượt khách nhất.',
      b:'Đúng. Nguồn lực có hạn đặt ở nơi mỗi nhân viên sẵn sàng chạm tới nhiều khách nhất.',
      c:'Tiện cho mình không phải tiêu chí; khách ở đâu thì đào tạo ở đó.',
      d:'Bốc thăm hợp với thử nghiệm đo tác động, còn ở đây mục tiêu là tối đa kết quả tuần đầu.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:tn05-04', skill:'insight', read:'6 phút', t:'Khách đầu tiên của sản phẩm mới nên là ai?',
  situation:'Một thương hiệu nước mắm nhỏ ở Phú Quốc ra dòng nước mắm nhĩ 40 độ đạm, giá 180.000 đồng/chai, gấp ba loại phổ thông. Đội marketing muốn chạy quảng cáo rộng cho mọi bà nội trợ ở TP.HCM. Trong danh sách khách cũ có 3.200 người đã mua loại 30 độ đạm ít nhất ba lần qua website.',
  concept:{ name:'Nhóm khách đầu tiên (beachhead)',
    body:'Sản phẩm mới không cần cả thị trường ngay. Nó cần một nhóm nhỏ mà <b>nhu cầu mạnh nhất, dễ với tới nhất và dễ nói lại với người khác nhất</b>. Nhóm này mua trước, cho phản hồi thật, tạo đánh giá và lời giới thiệu để nhóm lớn hơn tin theo. Thường đó là khách cũ đã tin thương hiệu, hoặc nhóm có vấn đề cụ thể mà sản phẩm giải quyết rõ nhất. Chọn đúng nhóm đầu giúp tiền quảng cáo đầu tiên không rải mỏng lên những người chưa sẵn sàng trả giá cao.' },
  example:'3.200 khách mua lặp lại đã tin chất lượng và quen mua online. Hãng gửi tin nhắn mời mua thử kèm tặng chai nhỏ 60 ml: 640 người mua, 20%. Họ để lại 150 đánh giá có ảnh trong tháng đầu. Khi chạy quảng cáo rộng ở tháng thứ hai, trang sản phẩm đã có bằng chứng từ người thật, tỉ lệ chuyển đổi cao hơn hẳn so với lúc trang còn trống.',
  takeaway:'Bán cho người sẵn sàng nhất trước; lời của họ là thứ thuyết phục nhóm tiếp theo.',
  apply:'Nói trong 60 giây: với một sản phẩm mới bạn biết, 500 khách đầu tiên là ai và bạn liên lạc họ bằng kênh nào.',
  mistakes:['Nhắm "tất cả mọi người" ngay từ đầu vì sợ bỏ sót khách.','Chọn nhóm đầu theo độ lớn, không theo mức sẵn sàng mua.'],
  q:[
  { type:'mcq', stem:'Đoán trước: sản phẩm cao cấp mới, ngân sách nhỏ. Nhóm khách nào có khả năng mua đầu tiên cao nhất?',
    options:[{k:'a',t:'Người trẻ hay xem TikTok, thích thử cái mới'},{k:'b',t:'Mọi bà nội trợ trong thành phố, vì ai cũng nấu ăn'},
             {k:'c',t:'Khách vãng lai đi chợ, siêu thị trong khu vực'},{k:'d',t:'Khách cũ đã mua lặp lại dòng sản phẩm gần nhất'}],
    answer:'d', why:{a:'Thích cái mới chưa chắc sẵn sàng trả giá gấp ba cho nước mắm.',
      b:'Nhóm quá rộng; phần lớn không sẵn sàng trả giá cao, tiền quảng cáo bị rải mỏng.',
      c:'Khách vãng lai chưa biết thương hiệu, khó chấp nhận giá cao ngay lần đầu.',
      d:'Đúng. Họ đã tin chất lượng và đã quen kênh mua; rào cản thấp nhất.'} },
  { type:'mcq', stem:'Bạn có 20 triệu đồng cho tháng đầu bán nước mắm nhĩ. Bạn chọn cách nào?',
    options:[{k:'a',t:'Chạy quảng cáo Facebook nhắm phụ nữ 25–55 tuổi ở TP.HCM'},{k:'b',t:'Thuê một KOL ẩm thực lớn làm một video giới thiệu'},
             {k:'c',t:'Nhắn cho 3.200 khách cũ mời mua thử, tặng chai nhỏ, xin đánh giá'},{k:'d',t:'In tờ rơi phát ở các chợ lớn tại quận 1, 3 và 5'}],
    answer:'c', why:{a:'20 triệu đồng rải trên hàng triệu người là quá mỏng cho một sản phẩm giá cao.',
      b:'Một video có thể tạo chú ý, nhưng khách lạ vào trang chưa có đánh giá nào sẽ ngần ngại.',
      c:'Đúng. Rẻ, nhắm đúng người sẵn sàng nhất, và tạo đánh giá cho giai đoạn sau.',
      d:'Người đi chợ phần lớn mua nước mắm phổ thông; tờ rơi khó thuyết phục trả giá gấp ba.'} },
  { type:'mcq', stem:'Vì sao đánh giá từ nhóm khách đầu tiên lại quan trọng với nhóm khách thứ hai?',
    options:[{k:'a',t:'Sàn thương mại điện tử bắt buộc có đủ đánh giá thì mới cho bán'},{k:'b',t:'Người mua mới dựa vào trải nghiệm của người thật để bớt lo mua sai'},
             {k:'c',t:'Đánh giá giúp thương hiệu tiết kiệm chi phí in bao bì cho lô sau'},{k:'d',t:'Có đánh giá thì được phép tăng giá bán lên ngay trong tháng thứ hai'}],
    answer:'b', why:{a:'Sàn không yêu cầu điều đó; nhưng khách thì nhìn vào đánh giá.',
      b:'Đúng. Với hàng giá cao, lời của người đã mua giảm cảm giác rủi ro.',
      c:'Đánh giá không liên quan tới chi phí bao bì.',
      d:'Đánh giá có thể hỗ trợ giá, nhưng đó không phải lý do chính khiến nhóm hai cần chúng.'} },
  { type:'mcq', stem:'Một phần mềm quản lý bán hàng mới cho quán ăn. Nhóm khách đầu tiên nào hợp lý nhất?',
    options:[{k:'a',t:'Chủ quán đang than phiền việc ghi order bằng giấy hay sai'},{k:'b',t:'Các chuỗi nhà hàng lớn đang dùng phần mềm quản lý của đối thủ'},
             {k:'c',t:'Tất cả quán ăn ở Hà Nội có đăng ký kinh doanh hợp lệ'},{k:'d',t:'Sinh viên ngành quản trị nhà hàng sắp tốt nghiệp năm nay'}],
    answer:'a', why:{a:'Đúng. Nỗi đau rõ và cụ thể; họ có lý do đổi ngay.',
      b:'Chuỗi lớn đã có hệ thống; đổi phần mềm tốn kém nên họ ít khi là người mua đầu.',
      c:'Nhóm quá rộng, gộp cả những quán chưa thấy mình có vấn đề.',
      d:'Sinh viên có thể thích sản phẩm, nhưng không phải người trả tiền.'} },
  { type:'calc', stem:'Hãng nhắn cho 3.200 khách cũ, 640 người mua thử. Trong số đó 150 người để lại đánh giá. Tỉ lệ người mua để lại đánh giá là bao nhiêu phần trăm? (làm tròn 1 chữ số thập phân)',
    unit:'%', ans:23.4, tol:0.1, wrong:[[4.7,'SAI_MAU_SO'],[20,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Mẫu số là người đã mua, không phải người nhận tin: 640.','150 ÷ 640 = 0,234 ≈ <b>23,4%</b>.'] },
  { type:'mcq', stem:'Sau tháng đầu, khách cũ mua nhiều nhưng hầu hết là người trên 45 tuổi. Đội muốn đổi hẳn sang nhắm người trẻ. Bạn góp ý gì?',
    options:[{k:'a',t:'Đổi ngay, vì người trẻ là tương lai của thương hiệu nước mắm'},{k:'b',t:'Dừng bán online, chuyển sang kênh siêu thị để gặp người trẻ'},
             {k:'c',t:'Mở rộng sang nhóm gần nhất, như người thân của khách cũ'},{k:'d',t:'Giảm giá mạnh để người trẻ chịu mua thử sản phẩm cao cấp'}],
    answer:'c', why:{a:'Bỏ nhóm đang mua tốt để đuổi nhóm chưa sẵn sàng là đốt chính lợi thế vừa có.',
      b:'Đổi kênh là một quyết định lớn khác, không giải quyết câu hỏi nhóm khách tiếp theo.',
      c:'Đúng. Mở rộng từng bước sang nhóm có đặc điểm gần với nhóm đang thắng.',
      d:'Giảm giá mạnh làm hỏng định vị cao cấp đang được nhóm đầu công nhận.'} },
  { type:'mcq', stem:'Vì sao "nhắm tất cả mọi người" là lựa chọn rủi ro cho ra mắt có ngân sách nhỏ?',
    options:[{k:'a',t:'Vì luật quảng cáo không cho phép nhắm quá nhiều nhóm tuổi cùng lúc'},{k:'b',t:'Vì người lớn tuổi không dùng mạng xã hội nên sẽ lãng phí'},
             {k:'c',t:'Vì đối thủ sẽ phát hiện và sao chép chiến dịch nhanh hơn'},{k:'d',t:'Vì tiền rải mỏng, thông điệp chung chung, không nhóm nào thấy đủ lý do'}],
    answer:'d', why:{a:'Không có giới hạn như vậy; vấn đề là hiệu quả, không phải quy định.',
      b:'Nhiều người lớn tuổi dùng mạng xã hội; đây không phải lý do chính.',
      c:'Đối thủ bắt chước được dù nhắm rộng hay hẹp.',
      d:'Đúng. Ngân sách nhỏ cộng thông điệp chung chung thì không đủ để ai hành động.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:tn05-05', skill:'measure', read:'7 phút', t:'Đặt mục tiêu gì cho tuần đầu và tháng đầu ra mắt?',
  situation:'Một thương hiệu sữa hạt ra mắt dòng mới trên Shopee và 200 cửa hàng tiện lợi. Giám đốc đặt mục tiêu duy nhất: 3 tỉ đồng doanh số tháng đầu. Tuần đầu đạt 500 triệu đồng, cả đội hoảng. Nhưng chưa ai xem có bao nhiêu người mua lần hai, hàng đã lên kệ ở bao nhiêu cửa hàng, hay khách đánh giá ra sao.',
  concept:{ name:'Mục tiêu theo giai đoạn',
    body:'Một con số doanh số cho cả tháng đầu che mất câu hỏi quan trọng: <b>trục trặc ở khâu nào</b>. Tốt hơn là đặt mục tiêu theo thứ tự các việc phải xảy ra. Tuần 1–2: hàng có mặt (độ phủ), khách thấy và mua thử (số người mua lần đầu). Tuần 3–4: khách quay lại (tỉ lệ mua lại), đánh giá tốt. Tháng 2–3 mới đến doanh số ổn định. Mỗi mốc là chỉ số dẫn dắt cho mốc sau. Nếu mốc đầu trượt, sửa ngay thay vì chờ cuối tháng mới biết doanh số hụt.' },
  example:'Hãng đặt lại: tuần 2 độ phủ 80% (160/200 cửa hàng), tuần 2 có 6.000 người mua thử, tuần 4 tỉ lệ mua lại 25%, điểm đánh giá từ 4,5 sao. Kiểm tra: độ phủ mới 55%, người mua thử 4.200, mua lại ở nhóm đầu 31%. Kết luận: sản phẩm ổn, khâu hụt là phủ hàng. Đội dồn sức đưa hàng ra 50 cửa hàng còn thiếu thay vì giảm giá.',
  takeaway:'Đặt mục tiêu theo thứ tự việc phải xảy ra; mốc nào trượt thì biết ngay khâu nào cần sửa.',
  apply:'Viết ba mốc cho tháng đầu của một sản phẩm: tuần 2, tuần 4, tuần 8, mỗi mốc một con số.',
  mistakes:['Chỉ đặt một mục tiêu doanh số cho cả tháng.','Hoảng vì doanh số tuần đầu và giảm giá trước khi biết khâu nào hụt.'],
  q:[
  { type:'mcq', stem:'Đoán trước: doanh số tuần đầu của sản phẩm mới chỉ bằng 1/6 mục tiêu tháng. Câu hỏi nào nên hỏi trước?',
    options:[{k:'a',t:'Có nên giảm giá ngay để kéo doanh số lên kịp mục tiêu tháng không'},{k:'b',t:'Khâu nào đang hụt: phủ hàng, người mua thử hay người mua lại'},
             {k:'c',t:'Có nên tăng gấp đôi ngân sách quảng cáo cho ba tuần còn lại không'},{k:'d',t:'Mục tiêu tháng có đặt quá cao so với năng lực của đội hay không'}],
    answer:'b', why:{a:'Giảm giá trước khi biết nguyên nhân có thể chữa sai bệnh và làm mỏng lãi.',
      b:'Đúng. Tách doanh số ra các khâu để biết sửa ở đâu.',
      c:'Nếu khâu hụt là phủ hàng thì thêm quảng cáo chỉ đổ tiền vào nơi không có hàng.',
      d:'Có thể mục tiêu cao, nhưng tuần đầu thường thấp hơn trung bình tháng; cần xem khâu nào trước khi kết luận.'} },
  { type:'mcq', stem:'Giám đốc muốn giữ một con số duy nhất để dễ báo cáo. Bạn đề xuất đặt mục tiêu thế nào?',
    options:[{k:'a',t:'Giữ doanh số làm đích, thêm các mốc phủ hàng, mua thử và mua lại theo tuần'},{k:'b',t:'Bỏ doanh số, chỉ theo dõi lượt xem video vì tháng đầu là giai đoạn nhận biết'},
             {k:'c',t:'Giữ đúng một mục tiêu doanh số, nhưng giảm từ 3 tỉ xuống 2 tỉ đồng cho an toàn'},{k:'d',t:'Đặt mục tiêu theo ngày để mỗi sáng biết ngay hôm qua đạt hay trượt doanh số'}],
    answer:'a', why:{a:'Đúng. Doanh số vẫn là đích; các mốc dẫn dắt cho biết đang đi đúng hướng chưa.',
      b:'Lượt xem không nói khách có mua hay quay lại không.',
      c:'Hạ mục tiêu không giúp biết khâu nào hụt.',
      d:'Doanh số theo ngày dao động mạnh và vẫn là một con số gộp, không chỉ ra nguyên nhân.'} },
  { type:'calc', stem:'Mục tiêu tuần 2: độ phủ 80% trên 200 cửa hàng. Thực tế hàng đã lên kệ ở 110 cửa hàng. Còn thiếu bao nhiêu cửa hàng để đạt mục tiêu?',
    unit:'cửa hàng', ans:50, tol:0.5, wrong:[[90,'SAI_MAU_SO'],[25,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_MAU_SO'],
    steps:['Mục tiêu: 200 × 80% = 160 cửa hàng.','Thiếu: 160 − 110 = <b>50 cửa hàng</b>.'] },
  { type:'mcq', stem:'Tuần 4: người mua thử vượt mục tiêu, nhưng tỉ lệ mua lại chỉ 9% so với mốc 25%. Bạn đọc thế nào?',
    options:[{k:'a',t:'Quảng cáo đang làm rất tốt, cần tăng ngân sách để thêm người mua thử'},{k:'b',t:'Phủ hàng đang yếu nên khách muốn mua lại mà không tìm thấy hàng'},
             {k:'c',t:'Tỉ lệ mua lại luôn thấp ở tháng đầu nên chưa cần quan tâm tới nó'},{k:'d',t:'Khách tò mò đã thử nhưng không quay lại: xem lại sản phẩm hoặc giá'}],
    answer:'d', why:{a:'Thêm người thử một sản phẩm ít ai quay lại là đổ nước vào thùng thủng.',
      b:'Có thể góp phần, nhưng khi người mua thử vượt mục tiêu thì hàng vẫn tìm thấy được; cần kiểm tra phía sản phẩm trước.',
      c:'9% so với 25% là hụt lớn, không phải dao động bình thường.',
      d:'Đúng. Thử nhiều mà quay lại ít chỉ ra vấn đề sau lần dùng đầu tiên.'} },
  { type:'mcq', stem:'Một khoá học online ra mắt. Mốc nào phù hợp nhất cho tuần đầu tiên?',
    options:[{k:'a',t:'Số học viên hoàn thành toàn bộ khoá học trong tuần đầu'},{k:'b',t:'Số người trả phí và tỉ lệ học xong bài đầu tiên trong 3 ngày'},
             {k:'c',t:'Doanh thu năm đầu dự kiến của khoá học theo kế hoạch'},{k:'d',t:'Số người đã theo dõi trang của người dạy trên Facebook'}],
    answer:'b', why:{a:'Khoá học thường kéo dài vài tuần; đo hoàn thành ngay tuần đầu là quá sớm.',
      b:'Đúng. Trả phí là mua thử; học bài đầu là dấu hiệu sớm của việc dùng thật.',
      c:'Dự kiến năm không phải thứ đo được ở tuần đầu.',
      d:'Theo dõi trang không cho biết ai trả tiền hay có học không.'} },
  { type:'mcq', stem:'Mốc tuần 2 về độ phủ trượt nặng. Việc nào nên làm ngay thay vì đợi cuối tháng?',
    options:[{k:'a',t:'Tìm xem kẹt ở nhà phân phối hay cửa hàng, và dồn đội bán hàng xử lý'},{k:'b',t:'Chờ cuối tháng xem doanh số tổng rồi mới quyết định phải làm gì'},
             {k:'c',t:'Đổi thông điệp quảng cáo để khách tò mò hơn về sản phẩm mới'},{k:'d',t:'Hạ mục tiêu độ phủ xuống để phù hợp thực tế của đội bán hàng'}],
    answer:'a', why:{a:'Đúng. Mốc sớm có giá trị chính vì cho phép sửa sớm.',
      b:'Đợi cuối tháng là bỏ phí ba tuần có thể sửa.',
      c:'Thông điệp không đưa hàng lên kệ.',
      d:'Hạ mục tiêu che vấn đề, không giải quyết nó.'} },
  { type:'mcq', stem:'Vì sao doanh số tuần đầu thường không nên nhân 4 để dự đoán doanh số tháng?',
    options:[{k:'a',t:'Vì tuần đầu luôn cao nhất do hiệu ứng ra mắt, các tuần sau chắc chắn giảm'},{k:'b',t:'Vì sàn thương mại điện tử chỉ tính doanh số sau khi khách đã nhận hàng'},
             {k:'c',t:'Vì độ phủ, người mua thử và người mua lại còn đang thay đổi từng tuần'},{k:'d',t:'Vì tháng có 30 ngày nên phải nhân với hệ số 4,3 thay cho con số 4'}],
    answer:'c', why:{a:'Không chắc chắn: tuần đầu có thể thấp vì hàng chưa phủ hết, hoặc cao vì tò mò.',
      b:'Cách ghi nhận có thể lệch vài ngày nhưng không phải lý do chính.',
      c:'Đúng. Các thành phần của doanh số còn đang dịch chuyển, nên nhân tuyến tính dễ sai.',
      d:'Đổi hệ số không sửa được việc giả định mọi tuần giống nhau.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:tn05-06', skill:'creative', read:'6 phút', t:'Có nên chạy teaser gây tò mò trước ngày ra mắt?',
  situation:'Một hãng giày nội địa định chi 150 triệu đồng cho hai tuần teaser trước khi mở bán mẫu mới: video bí ẩn, đếm ngược, không lộ sản phẩm. Ngày mở bán chỉ có 800 đôi, bán qua website. Trưởng nhóm hỏi: teaser có đáng không, hay dồn tiền vào tuần mở bán?',
  concept:{ name:'Teaser và điều kiện để nó có ích',
    body:'Teaser tạo chú ý trước khi khách mua được. Nó chỉ có ích khi sự chú ý <b>được giữ lại tới ngày mở bán</b>: người xem để lại số điện thoại, bấm nhắc lịch, theo dõi trang. Teaser hợp khi thương hiệu đã có người hâm mộ, sản phẩm có ngày mở bán rõ và hàng giới hạn khiến việc chờ đợi có ý nghĩa. Nó không hợp khi thương hiệu chưa ai biết, vì bí ẩn không có lý do để tò mò, hoặc khi chưa chắc hàng về đúng ngày. Cách đánh giá: tính <b>chi phí cho mỗi người đăng ký chờ</b> và xem bao nhiêu người đăng ký thật sự mua.' },
  example:'Hãng có 40.000 người theo dõi, lần mở bán trước hết hàng trong hai ngày. Teaser thu 4.000 người đăng ký nhắc lịch, chi phí 37.500 đồng/người. Ngày mở bán, 15% trong số đó mua, tức 600 đôi, phần lớn lô 800 đôi. Với hàng giới hạn và fan sẵn có, teaser làm được việc. Một thương hiệu mới chưa ai biết, cùng 150 triệu đồng, có thể chỉ thu vài trăm người đăng ký.',
  takeaway:'Teaser đáng khi khán giả đã quan tâm và sự chú ý được giữ lại tới ngày mở bán.',
  apply:'Nói trong 60 giây: sản phẩm bạn biết có nên teaser không, và bạn giữ người xem lại bằng cách nào.',
  mistakes:['Chạy teaser mà không có chỗ để người xem để lại liên lạc.','Teaser bí ẩn cho thương hiệu chưa ai biết.','Teaser rồi lùi ngày mở bán.'],
  q:[
  { type:'mcq', stem:'Đoán trước: teaser hai tuần tạo 2 triệu lượt xem. Con số nào cho biết teaser có hiệu quả thật?',
    options:[{k:'a',t:'Tổng lượt xem video trong hai tuần chạy teaser'},{k:'b',t:'Số bình luận đoán xem sản phẩm mới sẽ là gì'},
             {k:'c',t:'Số người để lại liên lạc và số trong đó mua khi mở bán'},{k:'d',t:'Số lượt chia sẻ video sang các trang cá nhân khác'}],
    answer:'c', why:{a:'Lượt xem nói về độ phủ, không nói người xem có quay lại mua không.',
      b:'Bình luận vui, nhưng không đo được việc mua.',
      c:'Đúng. Chú ý phải được giữ lại và chuyển thành mua thì teaser mới có giá trị.',
      d:'Chia sẻ lan rộng chú ý, nhưng vẫn chưa nói tới việc giữ người xem đến ngày bán.'} },
  { type:'mcq', stem:'Một thương hiệu mỹ phẩm mới chưa có người theo dõi, ngân sách 100 triệu đồng. Bạn chọn gì?',
    options:[{k:'a',t:'Hai tuần teaser bí ẩn, không lộ sản phẩm, để tạo sự tò mò'},{k:'b',t:'Thuê nhiều KOL đăng bài úp mở cùng lúc để tạo tin đồn'},
             {k:'c',t:'Chia đôi: nửa cho teaser, nửa cho tuần mở bán để an toàn'},{k:'d',t:'Dồn vào tuần mở bán, nói rõ sản phẩm và cho mua ngay'}],
    answer:'d', why:{a:'Không ai biết thương hiệu thì không ai có lý do tò mò về điều bí ẩn.',
      b:'Úp mở từ nhiều KOL cho một thương hiệu lạ dễ bị lướt qua như quảng cáo chung chung.',
      c:'Chia đôi làm cả hai phần đều mỏng; nửa teaser vẫn gặp đúng vấn đề chưa ai biết thương hiệu.',
      d:'Đúng. Khi chưa có khán giả, nói rõ sản phẩm và cho mua được ngay thường hiệu quả hơn.'} },
  { type:'calc', stem:'Teaser tốn 150 triệu đồng, thu 4.000 người đăng ký nhắc lịch. Chi phí cho mỗi người đăng ký là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:37.5, tol:0.1, wrong:[[26.7,'SAI_MAU_SO'],[375,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['150 triệu đồng = 150.000 nghìn đồng.','150.000 ÷ 4.000 = <b>37,5 nghìn đồng</b>/người.'] },
  { type:'mcq', stem:'4.000 người đăng ký, 600 người mua ngày mở bán. Nếu hàng về trễ một tuần và phải lùi ngày, điều gì dễ xảy ra nhất?',
    options:[{k:'a',t:'Khách sẽ chờ lâu hơn nên càng muốn mua, số đơn tăng lên'},{k:'b',t:'Một phần người đăng ký mất hứng, số mua thực tế giảm'},
             {k:'c',t:'Tất cả người đăng ký vẫn mua vì họ đã đăng ký rồi'},{k:'d',t:'Chi phí teaser được hoàn lại vì chưa bán được hàng'}],
    answer:'b', why:{a:'Chờ thêm hiếm khi làm tăng mong muốn; thường làm nguội.',
      b:'Đúng. Sự chú ý có hạn sử dụng; lùi ngày làm tiền teaser mất giá trị.',
      c:'Đăng ký không phải cam kết; nhiều người đổi ý hoặc quên.',
      d:'Tiền quảng cáo đã chi không được hoàn lại.'} },
  { type:'mcq', stem:'Trường hợp nào teaser hợp lý nhất?',
    options:[{k:'a',t:'Một hãng nước giặt ra thêm chai cỡ lớn hơn chai hiện tại'},{k:'b',t:'Một quán cơm mới mở ở trong hẻm, chưa có khách quen nào'},
             {k:'c',t:'Một thương hiệu có fan ra bộ sưu tập giới hạn có ngày bán'},{k:'d',t:'Một phần mềm kế toán nâng cấp thêm vài tính năng nhỏ'}],
    answer:'c', why:{a:'Chai cỡ lớn không có gì để tò mò; nói thẳng hiệu quả hơn.',
      b:'Chưa ai biết quán thì không ai tò mò; cần cho người ta thử ngay.',
      c:'Đúng. Có fan, có ngày bán, có giới hạn: đủ điều kiện để chờ đợi có ý nghĩa.',
      d:'Nâng cấp nhỏ nên thông báo rõ ràng, không cần bí ẩn.'} },
  { type:'mcq', stem:'Nội dung teaser được nhiều người khen sáng tạo, nhưng trang đăng ký nhắc lịch chỉ có 300 lượt. Nên sửa gì trước?',
    options:[{k:'a',t:'Làm video teaser bí ẩn hơn nữa để kích thích tò mò'},{k:'b',t:'Tăng ngân sách để nhiều người xem video teaser hơn'},
             {k:'c',t:'Đổi sang KOL khác nổi tiếng hơn để đăng video teaser'},{k:'d',t:'Đưa nút đăng ký lên rõ ràng và cho một lý do để đăng ký'}],
    answer:'d', why:{a:'Người xem đã thích nội dung; thêm bí ẩn không giúp họ để lại liên lạc.',
      b:'Tăng người xem mà tỉ lệ đăng ký vẫn thấp thì chi phí mỗi người đăng ký vẫn cao.',
      c:'Đổi KOL giải quyết lượt xem, trong khi khâu hụt nằm ở bước đăng ký.',
      d:'Đúng. Khâu hụt là chuyển chú ý thành đăng ký; sửa đúng khâu đó.'} },
  { type:'mcq', stem:'Sau hai lần teaser, hãng thấy chi phí mỗi người đăng ký gần bằng chi phí có một đơn hàng từ quảng cáo thường. Kết luận hợp lý?',
    options:[{k:'a',t:'Teaser tốt hơn vì người đăng ký là khách trung thành hơn hẳn'},{k:'b',t:'Chi phí gần nhau nên cứ chạy cả hai với ngân sách như cũ'},
             {k:'c',t:'Teaser đắt hơn: mỗi người đăng ký chưa phải là một đơn'},{k:'d',t:'Cần thêm KOL cho teaser để giảm chi phí mỗi người đăng ký'}],
    answer:'c', why:{a:'Chưa có bằng chứng người đăng ký trung thành hơn; cần so theo đơn.',
      b:'So sai đơn vị: một bên là người đăng ký, một bên là đơn hàng.',
      c:'Đúng. Nếu chỉ 15% người đăng ký mua, chi phí mỗi đơn từ teaser gấp khoảng 6–7 lần.',
      d:'Thêm KOL là thêm chi phí; chưa chắc làm giảm chi phí mỗi đơn.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:tn05-07', skill:'measure', read:'7 phút', t:'Ra mắt ế: đọc số nào để biết lỗi nằm ở đâu?',
  situation:'Một hãng mì ra vị lẩu Thái mới. Sau 6 tuần, doanh số chỉ đạt 40% kế hoạch. Cuộc họp chia phe: marketing nói do giá cao, bán hàng nói do quảng cáo yếu, sản xuất nói do đối thủ giảm giá. Không ai mang số liệu theo từng khâu.',
  concept:{ name:'Phễu ra mắt: có hàng – biết – thử – mua lại',
    body:'Doanh số của sản phẩm mới là tích của nhiều khâu: <b>hàng có ở điểm bán</b>, khách <b>biết</b> sản phẩm, khách <b>mua thử</b>, khách <b>mua lại</b>. Mỗi khâu có một con số: độ phủ, tỉ lệ nhận biết, tỉ lệ dùng thử, tỉ lệ mua lại. So từng con số với kế hoạch sẽ thấy khâu nào hụt nhiều nhất. Mỗi khâu hụt gợi ý một nguyên nhân khác: phủ thấp là chuyện phân phối; biết thấp là quảng cáo; biết cao mà thử thấp là giá, bao bì hay lời hứa; thử cao mà mua lại thấp là sản phẩm. Đọc phễu trước, tranh luận sau.' },
  example:'Kế hoạch: phủ 70%, nhận biết 50%, dùng thử 20%, mua lại 35%. Thực tế: phủ 68%, nhận biết 48%, dùng thử 19%, mua lại 14%. Ba khâu đầu gần như đạt, khâu cuối chỉ bằng 40% kế hoạch. Vậy không phải giá, không phải quảng cáo: khách đã mua thử nhưng không quay lại. Hãng thử lại vị ở 200 người, phát hiện vị chua quá gắt so với khẩu vị miền Bắc.',
  takeaway:'Tách doanh số thành các khâu; khâu hụt nhiều nhất cho biết phải sửa gì, không cần đoán.',
  apply:'Với một sản phẩm bạn biết đang bán chậm, viết bốn con số của phễu mà bạn cần thu thập.',
  mistakes:['Tranh luận nguyên nhân bằng cảm nhận trước khi có số từng khâu.','Chỉ nhìn doanh số tổng rồi giảm giá.'],
  q:[
  { type:'mcq', stem:'Đoán trước: ra mắt ế, ba phòng ban đổ lỗi cho nhau. Bước đầu tiên hợp lý là gì?',
    options:[{k:'a',t:'Lấy số của từng khâu: phủ, biết, thử, mua lại'},{k:'b',t:'Giảm giá ngay để cứu doanh số trong tháng này'},
             {k:'c',t:'Làm lại quảng cáo với KOL nổi tiếng hơn hiện tại'},{k:'d',t:'Để giám đốc chọn nguyên nhân và cả đội làm theo'}],
    answer:'a', why:{a:'Đúng. Số từng khâu biến tranh luận thành việc so sánh với kế hoạch.',
      b:'Giảm giá là giả thuyết của một phe; làm ngay là chọn phe chứ không phải tìm nguyên nhân.',
      c:'Quảng cáo chỉ là một khâu; làm lại khi chưa biết khâu nào hụt là đoán.',
      d:'Quyết định theo chức vụ không thay được dữ kiện.'} },
  { type:'mcq', stem:'Phủ 68%, nhận biết 48%, dùng thử 19% gần kế hoạch; mua lại 14% so với kế hoạch 35%. Bạn đề xuất sửa gì?',
    options:[{k:'a',t:'Giảm giá 20% để kéo thêm người mua thử trong tháng tới'},{k:'b',t:'Tăng ngân sách quảng cáo để nâng tỉ lệ nhận biết lên 60%'},
             {k:'c',t:'Kiểm tra lại vị sản phẩm với khách đã thử nhưng không mua lại'},{k:'d',t:'Mở rộng thêm điểm bán để độ phủ vượt 80% trong quý tới'}],
    answer:'c', why:{a:'Người mua thử đã gần đạt; giảm giá kéo thêm người thử một sản phẩm họ không quay lại.',
      b:'Nhận biết đã gần đạt; thêm quảng cáo không sửa việc khách thử xong bỏ đi.',
      c:'Đúng. Khâu hụt là mua lại, nên nhìn vào trải nghiệm sản phẩm.',
      d:'Phủ thêm chỉ đưa sản phẩm có vấn đề tới nhiều khách hơn.'} },
  { type:'calc', stem:'Một vùng có 1.000.000 hộ. Nhận biết 48%, trong người biết có 19% mua thử, trong người mua thử có 14% mua lại. Có bao nhiêu hộ mua lại? (bỏ qua độ phủ)',
    unit:'hộ', ans:12768, tol:1, wrong:[[190000,'QUEN_TI_LE_CHUYEN_DOI'],[91200,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Biết: 1.000.000 × 48% = 480.000 hộ.','Thử: 480.000 × 19% = 91.200 hộ.','Mua lại: 91.200 × 14% = <b>12.768 hộ</b>.'] },
  { type:'mcq', stem:'Một sản phẩm khác: nhận biết 55% (kế hoạch 50%), dùng thử 6% (kế hoạch 20%), phủ và mua lại đạt. Khâu nào cần xem?',
    options:[{k:'a',t:'Chất lượng sản phẩm, vì khách thử xong không hài lòng'},{k:'b',t:'Giá, bao bì hoặc lời hứa: biết rồi mà không muốn thử'},
             {k:'c',t:'Phân phối, vì có thể hàng chưa có mặt ở điểm bán'},{k:'d',t:'Quảng cáo, vì khách vẫn chưa biết tới sản phẩm này'}],
    answer:'b', why:{a:'Mua lại đạt, nghĩa là người đã thử thì hài lòng.',
      b:'Đúng. Biết cao mà thử thấp: rào cản nằm ở điều khiến khách ngần ngại lần đầu.',
      c:'Phủ đạt kế hoạch, nên không phải chuyện hàng không có.',
      d:'Nhận biết vượt kế hoạch; quảng cáo đã làm xong phần việc của nó.'} },
  { type:'mcq', stem:'Một ứng dụng học tiếng Anh: lượt tải cao, 70% đăng ký, nhưng chỉ 8% mở lại sau 7 ngày. Theo phễu, vấn đề nằm ở đâu?',
    options:[{k:'a',t:'Chiến dịch quảng cáo chưa đủ rộng để kéo người tải về'},{k:'b',t:'Kho ứng dụng hiển thị sai nên nhiều người vẫn chưa tìm ra'},
             {k:'c',t:'Giá gói trả phí quá cao nên người dùng chưa chịu đăng ký'},{k:'d',t:'Trải nghiệm tuần đầu chưa đủ lý do để người dùng quay lại'}],
    answer:'d', why:{a:'Lượt tải cao; khâu đầu phễu không phải vấn đề.',
      b:'Người dùng đã tải và đăng ký; họ tìm thấy ứng dụng.',
      c:'Đăng ký 70% là cao; giá chưa phải rào cản ở bước này.',
      d:'Đúng. Thử cao, quay lại thấp: tương đương mua lại thấp, chỉ về sản phẩm.'} },
  { type:'mcq', stem:'Vì sao không nên chỉ nhìn doanh số tổng khi ra mắt ế?',
    options:[{k:'a',t:'Cùng một doanh số thấp có thể do bốn khâu khác nhau gây ra'},{k:'b',t:'Doanh số tổng luôn bị trễ ít nhất hai tháng so với thực tế'},
             {k:'c',t:'Doanh số tổng không tính tới hàng tồn kho của nhà phân phối'},{k:'d',t:'Doanh số tổng thường bị phòng bán hàng báo cáo sai số liệu'}],
    answer:'a', why:{a:'Đúng. Một con số gộp không chỉ ra khâu nào cần sửa.',
      b:'Độ trễ tuỳ hệ thống, không phải lúc nào cũng hai tháng.',
      c:'Có thể đúng, nhưng lý do chính là doanh số không tách được nguyên nhân.',
      d:'Không cần giả định báo cáo sai; kể cả đúng thì vẫn không đủ để chẩn đoán.'} },
  { type:'mcq', stem:'Phủ chỉ 35% so với kế hoạch 70%, các khâu sau tính trên vùng có hàng đều đạt. Hành động nào đúng?',
    options:[{k:'a',t:'Làm lại công thức vì doanh số chỉ bằng một nửa kế hoạch'},{k:'b',t:'Sửa phân phối: đưa hàng tới nửa số điểm bán còn thiếu'},
             {k:'c',t:'Tăng quảng cáo toàn quốc để kéo khách tìm tới cửa hàng'},{k:'d',t:'Giảm giá để các tiệm tạp hoá thấy dễ bán và chịu nhập'}],
    answer:'b', why:{a:'Ở nơi có hàng, khách mua và mua lại đạt; sản phẩm không có vấn đề.',
      b:'Đúng. Khâu hụt duy nhất là phủ; sửa đúng khâu đó.',
      c:'Quảng cáo toàn quốc khi nửa số tiệm chưa có hàng là lãng phí.',
      d:'Giảm giá cho người tiêu dùng làm mỏng lãi; tiệm cần chính sách nhập hàng, không cần giá bán lẻ thấp hơn.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:tn05-08', skill:'brand', read:'7 phút', t:'Sản phẩm mới bán chạy nhưng lấy khách của chính sản phẩm cũ',
  situation:'Một hãng trà xanh đóng chai ra phiên bản không đường. Tháng đầu bán 200.000 chai, vượt kế hoạch. Nhưng trà xanh có đường của chính hãng giảm 120.000 chai so với cùng kỳ. Chai không đường lãi 3.000 đồng, chai có đường lãi 4.000 đồng. Giám đốc hỏi: ra mắt thành công hay thất bại?',
  concept:{ name:'Ăn thịt nội bộ (cannibalization)',
    body:'Khi sản phẩm mới lấy khách của sản phẩm cũ cùng hãng, một phần doanh số mới chỉ là tiền chuyển túi. Câu hỏi đúng không phải "sản phẩm mới bán bao nhiêu" mà là <b>tổng lợi nhuận của cả hãng tăng bao nhiêu</b>. Tính: lãi từ sản phẩm mới trừ lãi mất đi ở sản phẩm cũ. Ăn thịt nội bộ không phải lúc nào cũng xấu: nếu khách đằng nào cũng rời sản phẩm cũ sang đối thủ, thà họ chuyển sang sản phẩm mới của mình. Nhưng phải tính ra số, không nhìn riêng doanh số sản phẩm mới.' },
  example:'Lãi từ chai không đường: 200.000 × 3.000 = 600 triệu đồng. Lãi mất ở chai có đường: 120.000 × 4.000 = 480 triệu đồng. Lãi tăng thêm thực: 120 triệu đồng, chỉ bằng 1/5 con số đội báo cáo. Hãng vẫn giữ sản phẩm vì xu hướng giảm đường đang kéo khách đi, nhưng đổi quảng cáo sang nhắm người chưa uống trà xanh của hãng thay vì người đang uống.',
  takeaway:'Đo ra mắt bằng lãi tăng thêm của cả hãng, không bằng doanh số riêng của sản phẩm mới.',
  apply:'Nói trong 60 giây: sản phẩm mới nào bạn biết có thể lấy khách của sản phẩm cũ cùng hãng, và bạn đo điều đó thế nào.',
  mistakes:['Báo cáo doanh số sản phẩm mới như thể toàn bộ là khách mới.','Bỏ ra mắt chỉ vì có ăn thịt nội bộ, không xét việc khách đằng nào cũng rời đi.'],
  q:[
  { type:'mcq', stem:'Đoán trước: sản phẩm mới vượt kế hoạch doanh số. Điều gì có thể khiến lợi nhuận của cả hãng hầu như không tăng?',
    options:[{k:'a',t:'Chi phí quảng cáo cho sản phẩm mới quá lớn so với doanh số'},{k:'b',t:'Đối thủ cũng tung ra sản phẩm tương tự vào đúng thời điểm'},
             {k:'c',t:'Sản phẩm mới được bán giá thấp hơn giá của sản phẩm cũ'},{k:'d',t:'Khách của sản phẩm cũ chuyển sang, lãi cũ mất gần bằng lãi mới'}],
    answer:'d', why:{a:'Chi phí quảng cáo có thể lớn, nhưng không giải thích được việc lãi tổng đứng yên khi doanh số vượt kế hoạch.',
      b:'Đối thủ làm giảm doanh số của mình, không giải thích doanh số cao mà lãi tổng thấp.',
      c:'Giá thấp hơn chỉ là một phần; lý do chính là doanh số mới đến từ khách cũ.',
      d:'Đúng. Ăn thịt nội bộ làm doanh số mới đẹp nhưng lợi nhuận tổng tăng ít.'} },
  { type:'mcq', stem:'Lãi tăng thêm thực chỉ 120 triệu đồng. Bạn đề xuất gì cho quý tới?',
    options:[{k:'a',t:'Rút sản phẩm không đường ngay để bảo vệ trà xanh có đường'},{k:'b',t:'Giữ sản phẩm, nhắm quảng cáo vào người chưa uống trà của hãng'},
             {k:'c',t:'Tăng giá trà có đường để bù phần lãi đã mất trong tháng đầu'},{k:'d',t:'Tăng quảng cáo cho sản phẩm không đường để doanh số tăng gấp đôi'}],
    answer:'b', why:{a:'Nếu khách đang rời bỏ đồ có đường, rút sản phẩm mới chỉ đẩy họ sang đối thủ.',
      b:'Đúng. Giữ sản phẩm, nhưng hướng tăng trưởng vào khách mới để giảm phần ăn thịt.',
      c:'Tăng giá có thể đẩy thêm khách sang sản phẩm mới hoặc sang đối thủ.',
      d:'Tăng quảng cáo nhắm cùng tệp có thể kéo thêm khách cũ sang, ăn thịt nhiều hơn.'} },
  { type:'calc', stem:'Sản phẩm mới bán 200.000 chai, lãi 3.000 đồng/chai. Sản phẩm cũ giảm 120.000 chai, lãi 4.000 đồng/chai. Lãi tăng thêm thực của hãng là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:120, tol:0.5, wrong:[[600,'NHAM_SO_TUYET_DOI'],[240,'NHAM_GIA_VON']], errors:['NHAM_SO_TUYET_DOI'],
    steps:['Lãi mới: 200.000 × 3.000 = 600 triệu đồng.','Lãi mất: 120.000 × 4.000 = 480 triệu đồng.','Lãi tăng thêm: 600 − 480 = <b>120 triệu đồng</b>.'] },
  { type:'mcq', stem:'Khi nào chấp nhận sản phẩm mới ăn thịt sản phẩm cũ là hợp lý?',
    options:[{k:'a',t:'Khi khách của sản phẩm cũ đằng nào cũng rời đi sang đối thủ'},{k:'b',t:'Khi sản phẩm mới có bao bì đẹp hơn và mới mẻ hơn sản phẩm cũ'},
             {k:'c',t:'Khi đội marketing cần một chiến dịch mới để giữ nhịp truyền thông'},{k:'d',t:'Khi sản phẩm cũ đã có mặt trên thị trường hơn năm năm liên tục'}],
    answer:'a', why:{a:'Đúng. Giữ khách trong nhà bằng sản phẩm mới tốt hơn mất họ cho đối thủ.',
      b:'Bao bì đẹp không phải lý do kinh tế.',
      c:'Nhu cầu của đội không phải lý do để chấp nhận mất lãi.',
      d:'Tuổi của sản phẩm không quyết định; điều quyết định là khách có đang rời đi không.'} },
  { type:'mcq', stem:'Một chuỗi pizza ra combo 1 người giá 89.000 đồng. Số liệu nào giúp biết combo có ăn thịt pizza cỡ vừa không?',
    options:[{k:'a',t:'Tổng số combo bán ra trong tháng đầu tiên ra mắt'},{k:'b',t:'Số lượt thích bài đăng giới thiệu combo trên Facebook'},
             {k:'c',t:'Số pizza cỡ vừa bán ra trước và sau khi có combo'},{k:'d',t:'Đánh giá của khách về hương vị combo trên các ứng dụng'}],
    answer:'c', why:{a:'Số combo chỉ nói sản phẩm mới bán được bao nhiêu, không nói lấy từ đâu.',
      b:'Lượt thích không liên quan tới việc khách chuyển từ món này sang món khác.',
      c:'Đúng. So sản phẩm cũ trước và sau cho thấy phần bị lấy mất.',
      d:'Đánh giá vị nói về chất lượng, không nói về chuyển dịch giữa các món.'} },
  { type:'mcq', stem:'Đội báo cáo "sản phẩm mới đạt 5 tỉ đồng doanh thu". Câu hỏi nào nên hỏi tiếp?',
    options:[{k:'a',t:'Chi phí sản xuất mỗi đơn vị sản phẩm mới là bao nhiêu đồng'},{k:'b',t:'Bao nhiêu khách mới biết đến thương hiệu nhờ sản phẩm mới'},
             {k:'c',t:'Kế hoạch doanh thu năm sau cho sản phẩm mới là bao nhiêu'},{k:'d',t:'Sản phẩm cũ cùng hãng mất bao nhiêu trong cùng thời gian'}],
    answer:'d', why:{a:'Chi phí quan trọng, nhưng chưa trả lời phần doanh thu đến từ đâu.',
      b:'Khách mới là một phần câu trả lời, nhưng câu hỏi trực tiếp nhất là sản phẩm cũ mất bao nhiêu.',
      c:'Kế hoạch năm sau nói về tương lai, không kiểm tra con số hiện tại.',
      d:'Đúng. Phải trừ phần sản phẩm cũ mất đi mới biết đóng góp thật.'} },
  { type:'mcq', stem:'Cách nào giúp giảm ăn thịt nội bộ khi ra mắt?',
    options:[{k:'a',t:'Bán sản phẩm mới đúng giá sản phẩm cũ, ở đúng vị trí trên kệ'},{k:'b',t:'Định vị cho nhu cầu hoặc nhóm khách khác với sản phẩm cũ'},
             {k:'c',t:'Tạm ngừng quảng cáo sản phẩm cũ trong thời gian ra mắt'},{k:'d',t:'Đặt tên sản phẩm mới gần giống sản phẩm cũ để khách dễ nhớ'}],
    answer:'b', why:{a:'Cùng giá, cùng chỗ làm hai sản phẩm thành lựa chọn thay thế trực tiếp.',
      b:'Đúng. Khác nhu cầu, khác người dùng thì doanh số mới đến từ ngoài.',
      c:'Ngừng quảng cáo sản phẩm cũ đẩy thêm khách sang sản phẩm mới, tăng ăn thịt.',
      d:'Tên gần giống khiến khách xem hai sản phẩm như một, dễ chuyển qua lại.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:tn05-09', skill:'measure', read:'7 phút', t:'Khi nào nên rút một sản phẩm vừa ra mắt?',
  situation:'Một hãng bánh kẹo ra dòng bánh quy yến mạch 9 tháng trước. Mỗi tháng bán 25.000 gói, lãi gộp 4.000 đồng/gói. Riêng sản phẩm này tốn 80 triệu đồng/tháng phí trưng bày và 40 triệu đồng/tháng quảng cáo duy trì. Đã thử đổi bao bì và giảm giá, doanh số không nhúc nhích. Đội sản phẩm vẫn muốn "cho thêm thời gian".',
  concept:{ name:'Tiêu chí rút sản phẩm đặt từ trước',
    body:'Rút sản phẩm khó vì đã tốn nhiều công, và luôn có người hy vọng tháng sau sẽ khá hơn. Vì vậy tiêu chí rút nên <b>đặt ngay từ lúc ra mắt</b>: sau bao lâu, nếu mua lại dưới mức nào và lãi sau các chi phí riêng dưới mức nào thì rút. Khi xét, chỉ tính các chi phí <b>sẽ mất đi nếu rút</b>: phí trưng bày, quảng cáo riêng, phần sản xuất riêng. Tiền đã chi cho nghiên cứu là quá khứ, không lấy lại được, không nên giữ sản phẩm vì nó. Ngoài số, xét thêm chỗ trên kệ: sản phẩm yếu đang chiếm chỗ của một sản phẩm khác có thể bán tốt hơn.' },
  example:'Lãi gộp: 25.000 × 4.000 = 100 triệu đồng/tháng. Chi phí riêng: 80 + 40 = 120 triệu đồng/tháng. Mỗi tháng sản phẩm lỗ 20 triệu đồng sau chi phí riêng, và đã thử hai cách sửa không có kết quả. 2 tỉ đồng nghiên cứu ban đầu không liên quan tới quyết định. Hãng rút sản phẩm, dùng chỗ trên kệ cho vị bánh quy bơ đang thiếu hàng.',
  takeaway:'Đặt tiêu chí rút từ ngày ra mắt; khi xét chỉ đếm chi phí sẽ mất đi nếu rút, bỏ qua tiền đã tiêu.',
  apply:'Viết một câu tiêu chí rút cho một sản phẩm: "Sau … tháng, nếu … dưới … thì rút".',
  mistakes:['Giữ sản phẩm vì đã tốn nhiều tiền nghiên cứu.','Chỉ nhìn lãi gộp, quên phí trưng bày và quảng cáo riêng.'],
  q:[
  { type:'mcq', stem:'Đoán trước: sản phẩm có lãi gộp dương. Điều gì vẫn có thể khiến nên rút nó?',
    options:[{k:'a',t:'Sản phẩm đã có mặt trên thị trường hơn sáu tháng rồi'},{k:'b',t:'Đội bán hàng không thích bán sản phẩm này cho khách'},
             {k:'c',t:'Chi phí riêng cho nó lớn hơn lãi gộp nó mang về'},{k:'d',t:'Đối thủ có sản phẩm tương tự rẻ hơn khoảng 10%'}],
    answer:'c', why:{a:'Thời gian tự nó không phải lý do; nhiều sản phẩm cần hơn sáu tháng để lớn.',
      b:'Sở thích của đội bán hàng cần được hỏi lý do, không phải tiêu chí rút.',
      c:'Đúng. Lãi gộp dương nhưng sau phí trưng bày, quảng cáo riêng có thể âm.',
      d:'Đối thủ rẻ hơn là thông tin, nhưng nếu sản phẩm vẫn lãi sau chi phí riêng thì chưa phải lý do rút.'} },
  { type:'mcq', stem:'Đội sản phẩm muốn giữ bánh quy yến mạch vì "đã tốn 2 tỉ đồng nghiên cứu". Bạn chọn cách phản hồi nào?',
    options:[{k:'a',t:'2 tỉ đã tiêu không lấy lại được; chỉ xét lãi, lỗ từ nay về sau'},{k:'b',t:'Đồng ý giữ thêm một năm để thu hồi phần vốn 2 tỉ đồng đã bỏ ra'},
             {k:'c',t:'Tăng quảng cáo gấp đôi để doanh số đủ bù phần tiền nghiên cứu'},{k:'d',t:'Giảm giá thêm 20% để đẩy hàng và thu lại phần nào tiền đã bỏ ra'}],
    answer:'a', why:{a:'Đúng. Tiền đã chi không đổi dù giữ hay rút; giữ thêm chỉ làm lỗ thêm mỗi tháng.',
      b:'Mỗi tháng lỗ 20 triệu đồng sau chi phí riêng thì giữ thêm không thu hồi được gì.',
      c:'Tăng quảng cáo làm tăng chi phí riêng trong khi hai lần sửa trước đều không có kết quả.',
      d:'Giảm giá làm mỏng lãi gộp vốn đã không đủ bù chi phí riêng.'} },
  { type:'calc', stem:'Bán 25.000 gói/tháng, lãi gộp 4.000 đồng/gói. Phí trưng bày 80 triệu, quảng cáo riêng 40 triệu đồng/tháng. Lãi (lỗ) sau chi phí riêng mỗi tháng là bao nhiêu triệu đồng? (lỗ ghi số âm)',
    unit:'triệu đồng', ans:-20, tol:0.5, wrong:[[100,'QUEN_CHI_PHI_CO_DINH'],[20,'SAI_TINH_TOAN'],[60,'QUEN_TRU_CHI_PHI_QC']], errors:['QUEN_CHI_PHI_CO_DINH'],
    steps:['Lãi gộp: 25.000 × 4.000 = 100 triệu đồng.','Chi phí riêng: 80 + 40 = 120 triệu đồng.','100 − 120 = <b>−20 triệu đồng</b>/tháng.'] },
  { type:'mcq', stem:'Tiêu chí rút nào được viết tốt nhất khi ra mắt một sản phẩm?',
    options:[{k:'a',t:'Rút nếu sản phẩm không thành công như cả đội đã kỳ vọng'},{k:'b',t:'Rút khi giám đốc thấy sản phẩm không còn phù hợp chiến lược'},
             {k:'c',t:'Rút nếu đối thủ tung ra sản phẩm tốt hơn trong cùng ngành'},{k:'d',t:'Sau 6 tháng, mua lại dưới 20% và lỗ sau chi phí riêng thì rút'}],
    answer:'d', why:{a:'"Kỳ vọng" không đo được; ai cũng giải thích được theo ý mình.',
      b:'Phụ thuộc vào cảm nhận của một người, không phải tiêu chí.',
      c:'"Tốt hơn" không đo được, và đối thủ có sản phẩm tốt chưa chắc làm mình lỗ.',
      d:'Đúng. Có thời hạn, có con số, có ngưỡng: không cần tranh luận khi tới lúc.'} },
  { type:'mcq', stem:'Một sản phẩm lỗ nhẹ sau chi phí riêng, nhưng có tỉ lệ mua lại 45% và đang tăng đều mỗi tháng. Bạn nên làm gì?',
    options:[{k:'a',t:'Rút ngay vì đang lỗ, không còn lý do gì để giữ lại nữa cả'},{k:'b',t:'Giữ có thời hạn, theo dõi đà tăng, xem lại ngưỡng rút sau'},
             {k:'c',t:'Tăng giá mạnh để có lãi ngay trong tháng sau là xong'},{k:'d',t:'Cắt hết quảng cáo riêng để chuyển về có lãi ngay lập tức'}],
    answer:'b', why:{a:'Mua lại cao và đang tăng là dấu hiệu sản phẩm được khách giữ; lỗ có thể là tạm thời.',
      b:'Đúng. Giữ có thời hạn và điều kiện, không giữ vô hạn.',
      c:'Tăng giá mạnh có thể làm gãy đà đang tăng.',
      d:'Cắt hết quảng cáo có thể làm chậm đà tăng; cần tính trước khi cắt.'} },
  { type:'mcq', stem:'Vì sao "chỗ trên kệ" cũng là một chi phí khi xét giữ hay rút?',
    options:[{k:'a',t:'Chỗ đó có thể dành cho một sản phẩm khác bán tốt hơn'},{k:'b',t:'Siêu thị luôn thu phí trưng bày cao hơn với sản phẩm yếu'},
             {k:'c',t:'Sản phẩm để lâu trên kệ sẽ bị hỏng và phải tiêu huỷ'},{k:'d',t:'Kệ càng đầy thì khách càng khó tìm thấy sản phẩm chính'}],
    answer:'a', why:{a:'Đúng. Giá trị của chỗ trên kệ là thứ bạn bỏ lỡ khi để sản phẩm yếu chiếm nó.',
      b:'Không phải quy tắc chung; phí thường theo vị trí và hợp đồng.',
      c:'Hạn dùng là chuyện riêng, không phải lý do chỗ trên kệ là chi phí.',
      d:'Có thể xảy ra, nhưng lý do chính là cơ hội bị bỏ lỡ.'} },
  { type:'mcq', stem:'Sau khi quyết định rút, việc nào nên làm để không mất khách đang mua sản phẩm đó?',
    options:[{k:'a',t:'Rút lặng lẽ, không thông báo, để khách tự quên sản phẩm'},{k:'b',t:'Giảm giá sâu 70% để xả kho trong một tuần là xong'},
             {k:'c',t:'Gợi ý sản phẩm gần nhất của hãng cho khách đang mua nó'},{k:'d',t:'Giữ lại ở một vài siêu thị lớn để khách trung thành vẫn mua'}],
    answer:'c', why:{a:'Khách tìm không thấy sẽ chuyển sang đối thủ.',
      b:'Xả kho sâu có thể làm hỏng giá của các sản phẩm khác cùng hãng.',
      c:'Đúng. Giữ khách trong hãng bằng một lựa chọn thay thế.',
      d:'Vẫn phải trả phí trưng bày và quảng cáo; không giải quyết được vấn đề lỗ.'} }
  ] }

] });
